impactGrowthBox.css:
.growth-box {
  border-radius: 36px;
  padding: 36px;
  display: flex;
  flex-direction: column;
  gap: 24px;
  background: radial-gradient(closest-side, rgba(255, 245, 167, 1) 0%, rgba(255, 245, 167, 0.15) 100%);
  box-sizing: border-box;
}

.growth-header {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

.title-en {
  color: #333d4b;
  font-size: 40px;
  line-height: 1.1;
  font-weight: 800;
  margin: 0;
  letter-spacing: -0.03em;
}

.growth-subtitle {
  display: flex;
  align-items: center;
  gap: 8px;
  font-size: 20px;
  font-weight: 700;
  color: rgba(51, 61, 75, 0.7);
  cursor: pointer;
}

.growth-list {
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.service-card {
  background: #ffffff;
  border-radius: 999px;
  padding: 14px 20px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  color: #333d4b;
  font-size: 15px;
  font-weight: 600;
  cursor: pointer;
  box-shadow: 0 2px 6px rgba(0,0,0,0.03);
  transition: all 0.2s ease;
}

.service-card:hover {
  transform: translateX(4px);
}

.card-icon {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  background: #f2f4f6;
  display: flex;
  align-items: center;
  justify-content: center;
  color: #6b7684;
}

